                   for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)))
    diag = {p for p in cells if diagonal(p)}
    solid = cells - diag
    # A completely detached diagonal figure is preserved. Diagonal decorations
    # attached to, or vertically aligned with, an orthogonal figure are noise.
    solid_cols = {c for r, c in solid}
    for comp in comps(diag):
        attached = any(any((r+dr, c+dc) in solid
                           for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc)
                       for r, c in comp)
        aligned = any(c in solid_cols for r, c in comp)
        if attached or aligned:
            for r, c in comp:
                out[r][c] = bg
    # Complete vertical strokes belonging to orthogonal figures.
    cols = {}
    rows = {}
    for r, c in solid:
        cols.setdefault(c, []).append(r)
        rows.setdefault(r, []).append(c)
    for c, rs in cols.items():
        if len(rs) >= 4 and any((r, c-1) in solid or (r, c+1) in solid for r in rs):
            for r in range(min(rs), max(rs) + 1):
                out[r][c] = fg
    # Rejoin a broken horizontal stroke when the later fragment has no vertical
    # stroke of its own (and therefore is not a separate figure).
    for r, cs in rows.items():
        vals = sorted(set(cs))
        runs = []
        a = b = vals[0]
        for c in vals[1:]:
            if c != b + 1:
                runs.append((a, b))
                a = c
            b = c
        runs.append((a, b))
        for (a, b), (d, e) in zip(runs, runs[1:]):
            later_has_vertical = any(len(cols.get(c, [])) >= 4 for c in range(d, e+1))
            if not later_has_vertical:
                for c in range(b+1, d):
                    out[r][c] = fg
    # A diagonal continuing down-right from a horizontal endpoint indicates
    # that the horizontal stroke was cut off and continues to the boundary.
    for r, cs in rows.items():
        end = max(cs)
        if (r+1, end+1) in diag and (r+1, end+1) not in solid:
            for c in range(end+1, w):
                out[r][c] = fg
    return out
